/**
 * @description Background job that sends outbound transactions: builds the payloads, makes the callouts within the
 * callout time budget and the 100-callout limit (an Apex Auth send keeps room for its logins and one resend), saves
 * the outcome and chains itself for the rest. A transaction that cannot be sent is marked Failed; a temporary failure
 * is planned for auto-retry when its event allows it (IntegrationHubAutoRetry sends it again), otherwise it is retried
 * by hand. A finalizer marks the job's transactions Failed (temporary) if the job dies.
 * @group Integration Hub
 */
public with sharing class IntegrationHubSender implements Queueable, Database.AllowsCallouts {

    private static final Integer MAX_PER_JOB = 100;
    /** @description Attempt Kind of a send made by the automatic retry. */
    public static final String KIND_AUTO_RETRY = 'Auto Retry';
    private static final String NOT_SENT = 'Not sent: too many background jobs in this transaction.';
    private static final String FIELDS = 'Id, Name, Event__c, Event_Name__c, Direction__c, Status__c, Related_Record_Id__c, '
        + 'Related_Object__c, Request_Payload__c, Rebuild_Payload__c, Retry_Count__c, Correlation_Id__c, Target_Name__c, '
        + 'External_Reference_Id__c, Auto_Retries__c, Next_Retry_At__c';

    @TestVisible
    private static Boolean forceNoCapacity = false;
    /** Tests set a lower callout limit to check the guard; null uses Limits.getLimitCallouts(). */
    @TestVisible
    private static Integer calloutLimit;

    private final List<Id> ids;
    /** Transactions waiting for the business data job; handed on along the chain because a job can queue only one job. */
    private final List<Id> businessIds;
    /** Transactions sent by the auto-retry sweep: their attempts are logged as Auto Retry. Handed on along the chain. */
    private final Set<Id> autoIds;

    /**
     * @description A job for these transactions.
     * @param transactionIds the transactions
     */
    public IntegrationHubSender(List<Id> transactionIds) {
        this(transactionIds, new List<Id>(), new Set<Id>());
    }

    /* A job for these transactions that also hands on transactions waiting for the business data job and the auto-retry
       Ids (neither null). */
    private IntegrationHubSender(List<Id> transactionIds, List<Id> waitingForBusiness, Set<Id> autoRetryIds) {
        ids = transactionIds;
        businessIds = waitingForBusiness;
        autoIds = autoRetryIds;
    }

    /**
     * @description Queues a job for these transactions. When no more jobs can be queued in this transaction, they are
     * marked Failed (temporary) so nothing waits forever.
     * @param transactionIds the transactions
     */
    public static void enqueue(List<Id> transactionIds) {
        enqueueWith(transactionIds, new List<Id>(), new Set<Id>());
    }

    /* Queues one job: a send job carrying the business and auto-retry Ids on, or the business data job when nothing is
       left to send. */
    private static void enqueueWith(List<Id> transactionIds, List<Id> business, Set<Id> autoRetryIds) {
        if (transactionIds == null || transactionIds.isEmpty()) {
            IntegrationHubBusiness.enqueue(business);
        } else if (canEnqueue()) {
            System.enqueueJob(new IntegrationHubSender(transactionIds, business, autoRetryIds));
        } else {
            IntegrationHubRetryPlan.failAndSave(transactionIds, NOT_SENT, autoRetryIds);
            IntegrationHubBusiness.enqueue(business);
        }
    }

    /**
     * @description Trigger: a transaction whose status changes to Retry (a manual retry, or the auto-retry sweep, which
     * also raises Auto Retries) is sent at once, all of them in one job.
     * @param txns the updated transactions
     * @param oldMap their previous values
     */
    public static void onUpdate(List<IH_Transaction__c> txns, Map<Id, IH_Transaction__c> oldMap) {
        List<Id> retryNow = new List<Id>();
        for (IH_Transaction__c t : txns) {
            IH_Transaction__c old = oldMap == null ? null : oldMap.get(t.Id);
            Boolean changed = old == null || old.Status__c != t.Status__c;
            if (changed && t.Status__c == IntegrationHub.STATUS_RETRY && t.Direction__c == IntegrationHub.OUTBOUND) {
                retryNow.add(t.Id);
            }
        }
        enqueueWith(retryNow, new List<Id>(), IntegrationHubRetryPlan.raisedIds(txns, oldMap));
    }

    /**
     * @description Sends the transactions.
     * @param qc the queueable context
     */
    public void execute(QueueableContext qc) {
        List<IH_Transaction__c> txns = load();
        List<Id> loaded = new List<Id>(new Map<Id, IH_Transaction__c>(txns).keySet());
        System.attachFinalizer(new Recovery(loaded).carrying(businessIds));
        List<Id> business = new List<Id>(businessIds);
        if (txns.isEmpty()) {
            IntegrationHubBusiness.enqueue(business);
            return;
        }
        List<IntegrationHubCallout.Delivery> deliveries = IntegrationHubOutcome.prepare(txns);
        List<Id> rest = send(deliveries);
        business.addAll(IntegrationHubOutcome.runHandlers(deliveries));
        IntegrationHubData.updateEach(txns);
        logAttempts(deliveries, autoRetryIds());
        IntegrationHubBodyFiles.save(IntegrationHubBodyFiles.responseFiles(deliveries));
        chain(new Set<Id>(loaded), rest, business);
    }

    private static void logAttempts(List<IntegrationHubCallout.Delivery> deliveries, Set<Id> autoRetryIds) {
        List<IH_Attempt__c> attempts = new List<IH_Attempt__c>();
        for (IntegrationHubCallout.Delivery d : deliveries) {
            if (d.attempted) {
                IH_Attempt__c a = attemptRecord(d);
                a.Kind__c = autoRetryIds.contains(d.txn.Id) ? KIND_AUTO_RETRY : a.Kind__c;
                attempts.add(a);
            }
        }
        if (!attempts.isEmpty()) {
            IntegrationHubData.insertEach(attempts);
        }
    }

    private List<IH_Transaction__c> load() {
        return (List<IH_Transaction__c>) IntegrationHubData.query(
            'SELECT ' + FIELDS + ' FROM IH_Transaction__c WHERE Direction__c = :dir AND Status__c IN :open AND Id IN :ids '
            + 'ORDER BY CreatedDate LIMIT ' + MAX_PER_JOB,
            new Map<String, Object>{
                'dir' => IntegrationHub.OUTBOUND,
                'open' => new List<String>{ IntegrationHub.STATUS_PENDING, IntegrationHub.STATUS_RETRY },
                'ids' => ids == null ? new List<Id>() : ids
            });
    }

    @TestVisible
    private static List<Id> send(List<IntegrationHubCallout.Delivery> deliveries) {
        List<Id> rest = new List<Id>();
        Long started = System.currentTimeMillis();
        for (IntegrationHubCallout.Delivery d : deliveries) {
            if (d.txn.Status__c == IntegrationHub.STATUS_FAILED) {
                continue;
            }
            if (!IntegrationHubConnectionAuth.fitsInJob(d, System.currentTimeMillis() - started, calloutLimit)) {
                rest.add(d.txn.Id);
                continue;
            }
            IntegrationHubCallout.deliver(d);
        }
        return rest;
    }

    /* A job queued before this version was deployed has no auto-retry Ids. */
    private Set<Id> autoRetryIds() {
        return autoIds == null ? new Set<Id>() : autoIds;
    }

    /* A job can queue one job: the next send job (which carries the business Ids on) or else the business data job. */
    private void chain(Set<Id> loaded, List<Id> rest, List<Id> business) {
        List<Id> next = new List<Id>(rest);
        for (Id txnId : ids == null ? new List<Id>() : ids) {
            if (!loaded.contains(txnId)) {
                next.add(txnId);
            }
        }
        enqueueWith(Test.isRunningTest() ? new List<Id>() : next, business, autoRetryIds());
    }

    /**
     * @description The Integration Attempt record of a delivery that was tried: when, the result, the HTTP status, the
     * answer (first 131,072 characters) and the error. Call after the outcome (and any response handler) was applied.
     * @param d the delivery
     * @return the attempt, not inserted
     */
    @TestVisible
    private static IH_Attempt__c attemptRecord(IntegrationHubCallout.Delivery d) {
        IH_Transaction__c t = d.txn;
        Boolean failed = t.Status__c == IntegrationHub.STATUS_FAILED;
        return new IH_Attempt__c(Transaction__c = t.Id, Attempted_At__c = t.Last_Attempt__c, Outcome__c = t.Status__c,
            Http_Status_Code__c = d.res == null ? null : d.res.getStatusCode(), Payload_Used__c = d.payloadUsed, Kind__c = 'Send',
            Response_Body__c = d.res == null ? null : IntegrationHub.clip(d.res.getBody(), IntegrationHubBodyFiles.FIELD_MAX),
            Error_Message__c = failed ? t.Error_Message__c : null, Error_Summary__c = failed ? t.Error_Summary__c : null);
    }

    @TestVisible
    private static Boolean canEnqueue() {
        return !forceNoCapacity && Limits.getQueueableJobs() < Limits.getLimitQueueableJobs();
    }

    /**
     * @description Marks the job's transactions that are still Pending or Retry as Failed (temporary, so auto-retry
     * applies where the event allows it) when the job dies.
     */
    public class Recovery implements Finalizer {
        private final List<Id> txnIds;
        private List<Id> waitingIds = new List<Id>();

        /**
         * @description Recovery for these transactions.
         * @param transactionIds the job's transactions
         */
        public Recovery(List<Id> transactionIds) {
            txnIds = transactionIds;
        }

        /**
         * @description The transactions this job carried for the business job; handed on if the job dies.
         * @param businessIds transactions waiting for the business job
         * @return this recovery
         */
        public Recovery carrying(List<Id> businessIds) {
            waitingIds = businessIds == null ? new List<Id>() : businessIds;
            return this;
        }

        /**
         * @description Runs after the job.
         * @param ctx the finalizer context
         */
        public void execute(FinalizerContext ctx) {
            if (ctx.getResult() == ParentJobResult.SUCCESS) {
                return;
            }
            if (!waitingIds.isEmpty()) {
                IntegrationHubBusiness.enqueue(waitingIds);
            }
            if (txnIds == null || txnIds.isEmpty()) {
                return;
            }
            List<Id> stuck = new List<Id>(new Map<Id, SObject>(IntegrationHubData.query(
                'SELECT Id FROM IH_Transaction__c WHERE Id IN :ids AND Status__c IN :open',
                new Map<String, Object>{ 'ids' => txnIds, 'open' => new List<String>{ IntegrationHub.STATUS_PENDING, IntegrationHub.STATUS_RETRY } })).keySet());
            String reason = ctx.getException() == null ? 'The send job stopped.' : 'The send job stopped: ' + ctx.getException().getMessage();
            IntegrationHubRetryPlan.failAndSave(stuck, reason);
        }
    }
}
